window.WIKI_SOURCES={"patch":{"name":"Официальный Update VIII — Retrain, боевые изменения","url":"https://store.steampowered.com/news/posts/?enddate=1670324686&feed=steam_community_announcements"},"patch13":{"name":"Официальные обновления игры / Update XIII","url":"https://steamcommunity.com/app/1611910/announcements/"},"pcg":{"name":"PC Gamer — гайд для новичков","url":"https://www.pcgamer.com/warhammer-40k-chaos-gate-daemonhunters-guide/"},"ship":{"name":"PC Invasion — модули корабля","url":"https://www.pcinvasion.com/warhammer-chaos-gate-daemonhunters-%E2%81%A0ship-upgrades-guide/"},"research":{"name":"PC Invasion — исследования","url":"https://www.pcinvasion.com/warhammer-chaos-gate-daemonhunters-%E2%81%A0research-tech-guide/"},"gear":{"name":"GameSkinny — улучшение оружия и брони","url":"https://www.gameskinny.com/tips/warhammer-40k-chaos-gate-daemonhunters-how-to-unlock-weapon-and-armor-upgrades/"},"classes":{"name":"PC Gamer — классы","url":"https://www.pcgamer.com/warhammer-40k-chaos-gate-daemonhunters-classes/"},"recruits":{"name":"Pro Game Guides — продвинутые классы","url":"https://progameguides.com/warhammer-40000-chaos-gate-daemonhunters/how-to-unlock-advanced-classes-in-warhammer-40000-chaos-gate-daemonhunters/"},"classguide":{"name":"MercytheMad — Steam-гайд по Legendary/Прогностикарам","url":"https://steamcommunity.com/sharedfiles/filedetails/?id=2805846491"},"prognost":{"name":"MercytheMad — размещение Прогностикаров (видео)","url":"https://www.youtube.com/watch?v=d-yiPilsGgg"},"traits":{"name":"Steam Community — все пассивные таланты","url":"https://steamcommunity.com/sharedfiles/filedetails/?id=2806137413"},"mastery":{"name":"TrueAchievements — True Mastery и очки после 9 ранга","url":"https://www.trueachievements.com/a425892/true-mastery-achievement"},"commune":{"name":"Steam Community — как работает Commune","url":"https://steamcommunity.com/app/1611910/discussions/0/3768984079236816456/"},"respec":{"name":"Steam Community — Retrain за 2 Requisition","url":"https://steamcommunity.com/app/1611910/discussions/0/3600093929976730868/"},"aug":{"name":"Hoplite — аугметика (видео)","url":"https://www.youtube.com/watch?v=mBYqF8yZlA0"},"forum":{"name":"Сообщество — подробный разбор оптимизации билдов","url":"https://forums.somethingawful.com/showthread.php?threadid=4058207&userid=139510"},"levels":{"name":"Steam Community — сколько очков даёт павший рыцарь","url":"https://steamcommunity.com/app/1611910/discussions/0/3820796140086125576/"},"paladin":{"name":"Chaos Gate Wiki — Paladin","url":"https://chaosgate.fandom.com/wiki/Paladin"},"bosses":{"name":"Chaos Gate Wiki — враги/боссы","url":"https://chaosgate.fandom.com/wiki/Warhammer_40,000:_Chaos_Gate_Wiki"}};
window.WIKI=[{"id":"start","title":"С чего начать","group":"Основы","summary":"План для первых часов — без сюжетных спойлеров","body":"<p>Это справочник для <b>Warhammer 40,000: Chaos Gate — Daemonhunters</b>: только основная игра и DLC <b>Castellan Garran Crowe</b>. Без Duty Eternal, Execution Force, технодесантника, дредноута и ассасинов.</p><div class=\"note tip\"><b>Три правила победы на Legendary</b><div>1) Открывай патруль полной и подготовленной четвёркой. 2) Трать AP на удаление угроз, а не на случайный урон. 3) На корабле прежде всего запускай производство сервиторов, развивай скорость и доступ к сильному снаряжению.</div></div><h3>Твои ближайшие цели</h3><ol><li>Развивай <b>Interceptor + Justicar + Purgator + Apothecary</b>. Позже можешь заменить Апотекария на Библиария.</li><li>Собери билд Инцептора вокруг <b>Teleport + Hammerhand + Ruthless Precision</b>.</li><li>Юстикару открой <b>Honour the Chapter</b> — передачу AP.</li><li>Исследуй <b>Advanced Seed Access</b> для Extractor Servo-Skull — сбор семян без расхода AP.</li><li>На корабле восстанови <b>Augmentation Chamber</b>; затем скорость двигателя и Meditation Chamber.</li><li>Не расставляй всех Прогностикаров до расширения карты.</li><li>На первом этапе не расходуй реквизицию на каждого встречного рекрута.</li></ol><h3>Разделы для быстрого доступа</h3><ul><li><a href=\"#quick\">20 лучших советов</a></li><li><a href=\"#respec\">Переобучение</a></li><li><a href=\"#augmetics\">Аугметика</a></li><li><a href=\"#overcap\">Сверхлимитная прокачка</a></li><li><a href=\"#ship\">Корабль</a></li><li><a href=\"#classes\">Все классы</a></li><li><a href=\"#enemies\">Опасные враги</a></li><li><a href=\"#bosses\">Боссы: тактики</a></li><li><a href=\"#glossary\">Баффы и дебаффы</a></li></ul><div class=\"note warn\"><b>Что не стоит делать</b><div>Не пытайся собрать весь опыт на четырёх героях: к финалу пригодятся восемь нормальных бойцов. Не сохраняй каждую гранату «на потом»: своевременный взрыв зачастую экономит ранения.</div></div>","refs":["pcg","classguide","patch"],"tags":["начало","новичку","старт"]},{"id":"quick","title":"20 главных фишек","group":"Основы","summary":"Короткая выжимка для телефона — перед любой миссией","body":"<div class=\"table-wrap\"><table><thead><tr><th>#</th><th>Фишка</th><th>Почему это работает</th></tr></thead><tbody><tr><td>01</td><td><b>Сближай бойцов до контакта</b></td><td>При обнаружении новой группы AP команды обновляются до трёх: открывай её только готовым отрядом.</td></tr><tr><td>02</td><td><b>Перемещай отставших первыми</b></td><td>Так разведчик не активирует патруль, когда трое рыцарей далеко.</td></tr><tr><td>03</td><td><b>Один патруль за раз</b></td><td>Смешение двух групп — частая причина поражения на Legendary.</td></tr><tr><td>04</td><td><b>Justicar = батарейка AP</b></td><td>Honour the Chapter отдаёт действия лучшему убийце.</td></tr><tr><td>05</td><td><b>Инцептор = криты + возврат AP</b></td><td>Teleport, Hammerhand, Ruthless Precision и Focus делают цепочки убийств.</td></tr><tr><td>06</td><td><b>Крит = выключенное оружие</b></td><td>Precision Targeting часто выгоднее дополнительного урона.</td></tr><tr><td>07</td><td><b>Extractor Skull пораньше</b></td><td>Семена для исследований и Purity Seals собираются без траты AP.</td></tr><tr><td>08</td><td><b>Execute раздаёт AP</b></td><td>Оглушение + добивание — отдельная экономика действий; на Legendary требуется подготовка.</td></tr><tr><td>09</td><td><b>Используй пропасти</b></td><td>Взрыв с Knockback может уничтожить толстого врага мгновенно.</td></tr><tr><td>10</td><td><b>Не бей первым бронированную махину</b></td><td>Убей хирурга/проповедника/призывателя, который усиливает группу.</td></tr><tr><td>11</td><td><b>Disrupted против автоатак</b></td><td>Отключает реакционные способности, в том числе неприятные атаки летающих дронов.</td></tr><tr><td>12</td><td><b>Warp Surge планируй</b></td><td>Не оставляй шкалу почти полной посреди растянутой группы.</td></tr><tr><td>13</td><td><b>Броня +1 AP лучше HP</b></td><td>Один новый удар или перемещение в каждом ходу часто спасает больше здоровья.</td></tr><tr><td>14</td><td><b>Не все Tier III лучше Tier II</b></td><td>Смотри синергию, прокачку Purity Seals и ограничения билда.</td></tr><tr><td>15</td><td><b>Сервиторы = экономика</b></td><td>Augmentation Chamber нужно ставить как можно раньше.</td></tr><tr><td>16</td><td><b>Скорость корабля = больше миссий</b></td><td>Warp Drive позволяет успеть за сервиторами, семенами и предметами.</td></tr><tr><td>17</td><td><b>Не трать всех Прогностикаров</b></td><td>После расширения карты их нельзя удобно передвинуть.</td></tr><tr><td>18</td><td><b>Ретрен доступен за реквизицию</b></td><td>После Update VIII для обычного Retrain не требуется погибший рыцарь.</td></tr><tr><td>19</td><td><b>9 ранг — не потолок навыков</b></td><td>Commune with the Fallen даёт дополнительные очки поверх 18 стандартных.</td></tr><tr><td>20</td><td><b>К финалу нужно 8 бойцов</b></td><td>Одна команда бьёт Мортариона, другая удерживает портал.</td></tr></tbody></table></div><div class=\"note tip\"><b>Если помнить только одну мысль</b><div>Каждое твоё действие должно уменьшать количество <b>опасных действий врага на следующем ходу</b>. Убийство лекаря, отключение пушки и срыв ритуала ценнее красивого, но бесполезного урона.</div></div>","refs":["pcg","patch","classguide","mastery"],"tags":["фишки","советы","типсы","памятка"]},{"id":"respec","title":"Как переобучать рыцарей","group":"Неочевидное","summary":"Обычный Retrain за 2 реквизиции и мгновенный Commune","body":"<div class=\"note good\"><b>Важно: старые гайды устарели</b><div>В Update VIII (6 декабря 2022) добавили <b>обычное переобучение за Requisition</b>. Жертвовать рыцарем не нужно.</div></div><h3>Способ 1. Retrain — без погибших</h3><ol><li>Открой <b>Barracks</b> на корабле и выбери рыцаря.</li><li>Зайди во вкладку <b>Abilities</b> — дерево навыков.</li><li>Выбери <b>Retrain</b> и оплати <b>2 Requisition</b>.</li><li>На время обучения боец уходит <b>On Assignment</b> и недоступен.</li><li>После возвращения перераспредели очки в дереве способностей.</li></ol><p>Ранг, класс и опыт сохраняются. Это главный способ исправить плохую прокачку у рекрута высокого уровня. Конкретное время отсутствия показывается в интерфейсе.</p><h3>Способ 2. Commune with the Fallen — мгновенный</h3><ol><li>Построй <b>Stasis Chamber</b> в улучшениях Apothecarion.</li><li>Если рыцарь погиб окончательно, его останки могут храниться в камере.</li><li>Открой Barracks → живой рыцарь → Abilities → <b>Commune</b>.</li><li>Выбери <b>либо мгновенный сброс навыков, либо бонусные очки</b>. Один погибший — одно использование.</li></ol><div class=\"note tip\"><b>Не путай</b><div>Retrain за реквизицию <b>не даёт новых очков</b>. Commune может дать дополнительные очки сверх 9-го ранга; для этого нужен погибший рыцарь.</div></div><p>Смотри также: <a href=\"#overcap\">прокачка сверх 9-го ранга</a> и <a href=\"#augmetics\">критические ранения / аугметика</a>.</p>","refs":["patch","respec","commune","mastery"],"tags":["сброс","ресет","переобучение","retrain","commune"]},{"id":"augmetics","title":"Аугметика и Resilience","group":"Неочевидное","summary":"Как получить пять имплантов и не потерять бойца","body":"<h3>Как работает</h3><ol><li>Улучши корабельный <b>Apothecarion → Surgical Unit</b>.</li><li>Рыцарь получает <b>Critical Wound</b> в бою, но не погибает окончательно.</li><li>После восстановления в медотсеке получает случайную аугметику с постоянным бонусом.</li><li>Возможно получить <b>до пяти</b> имплантов на одного бойца.</li></ol><div class=\"note warn\"><b>Риск на Legendary</b><div>С каждым тяжёлым ранением расходуется Resilience — запас, от которого зависит возможность пережить следующее критическое поражение. Не рекомендуется специально калечить основного Инцептора ради случайного +5% к криту.</div></div><h3>Самые полезные аугметики</h3><div class=\"table-wrap\"><table><thead><tr><th>Аугметика</th><th>Эффект</th><th>Кому</th></tr></thead><tbody><tr><td>Synthmuscle</td><td>+5% шанс крита ближним оружием</td><td>Инцептор</td></tr><tr><td>Augmetic Elbow</td><td>+1 к урону критов в ближнем бою</td><td>Инцептор</td></tr><tr><td>Cortex Implant</td><td>+5% Focus — шанс срабатывания автонавыков</td><td>Инцептор</td></tr><tr><td>Armour Reinforcement</td><td>+1 броня</td><td>Ближний бой / саппорт</td></tr><tr><td>Psi-Booster</td><td>+1 WP — ресурс психических умений</td><td>Юстикар / Библиарий</td></tr><tr><td>Augmetic Eye</td><td>+5% шанс крита из огнестрельного оружия</td><td>Пургатор</td></tr><tr><td>Cerebral Implant</td><td>+25% XP за убийство</td><td>Развивающийся боец</td></tr></tbody></table></div><h3>Таланты, с которыми аугметика особенно хороша</h3><ul><li><b>Omnissiah's Chosen</b> — удваивает эффект имплантов; редкая сильная синергия.</li><li><b>Deathless</b> — снижает риск потери персонажа при критической травме, но с ценой в WP.</li><li><b>Castellan Crowe</b> — исключение: не получает аугметику; это подтверждено патчем.</li></ul><p>По остальным врождённым талантам смотри <a href=\"#traits\">редкие таланты</a>.</p>","refs":["traits","aug","pcg","patch13"],"tags":["кибернетика","ранения","операции","импланты","аугментации","resilience"]},{"id":"overcap","title":"Прокачка после 9-го ранга","group":"Неочевидное","summary":"18 обычных очков + дополнительные через погибших","body":"<p>Обычный максимум — <b>ранг 9</b>. За прокачку дают <b>18 обычных очков навыков</b>. 10-го ранга нет. Но отдельная механика позволяет получить ещё очки, не повышая ранг.</p><h3>Commune: сколько дополнительных очков</h3><div class=\"table-wrap\"><table><thead><tr><th>Ранг павшего рыцаря</th><th>Бонус получателю</th></tr></thead><tbody><tr><td>1–4</td><td>+1 очко</td></tr><tr><td>5–8</td><td>+2 очка</td></tr><tr><td>9</td><td>+3 очка</td></tr></tbody></table></div><p>Для этого нужен <b>Stasis Chamber</b> и останки окончательно погибшего рыцаря. В Barracks → Abilities → Commune выбирай именно <b>bonus points</b>, а не сброс навыков.</p><div class=\"note tip\"><b>Теоретический максимум</b><div>В дереве — 36 навыков. Чтобы открыть всё после стандартных 18 очков, понадобится ещё 18, например от шести погибших рыцарей 9-го ранга.</div></div><p>На Legendary специально выкачивать «всё» обычно неразумно. Особенно важно уметь использовать 18 очков по роли. Для достижения True Mastery такой путь действительно существует.</p><p>Путаница: <a href=\"#respec\">обычный Retrain</a> возвращает потраченные очки, но не создаёт новых.</p>","refs":["mastery","levels","commune"],"tags":["9","10","макс","уровень","навыки","очки","коммуна"]},{"id":"advanced","title":"Как открыть продвинутые классы","group":"Неочевидное","summary":"Библиарий, Капеллан, Паладин и Очиститель без DLC","body":"<p>Все четыре продвинутых класса входят в базовую игру. Их доступ привязан к сюжетной линии, прежде всего <b>The Nexus</b> и последующим событиям.</p><ol><li>Продвигай исследования семян, пока не станет доступна миссия <b>The Nexus</b>.</li><li>Выполни The Nexus и дождись событий Великого магистра Кая.</li><li>В одном из событий можно получить продвинутого рыцаря. <b>Рекомендую Librarian</b>.</li><li>Далее продвинутые классы могут появиться в <b>наградах Bloom-миссий</b>. На звёздной карте наведи на иконку шлема, чтобы увидеть конкретный класс.</li><li>Проверь наличие <b>Requisition и свободного слота в Barracks</b> перед получением награды.</li></ol><h3>Особые способы</h3><ul><li>Отдельное событие позволяет избранному рыцарю пройти обучение и стать <b>Paladin</b> (есть риск потерять его в случае неудачного события).</li><li>Обычный Retrain класс не меняет.</li><li>Уровень Knight Requisition влияет на ранг новых бойцов, но не гарантирует нужный класс.</li></ul><p>Рекомендуемый порядок: <b>Librarian → Chaplain</b>, а Paladin и Purifier — по составу команды.</p>","refs":["recruits","paladin","patch"],"tags":["либрариан","классы","продвинутые","нексус","наём"]},{"id":"traits","title":"Редкие таланты и события","group":"Неочевидное","summary":"Какие врождённые таланты искать у рекрутов","body":"<p>Врождённый Talent — не обычный навык дерева. При найме рыцарю случайно достаётся пассивный бонус; некоторые сюжетные события могут добавлять новые таланты.</p><div class=\"table-wrap\"><table><thead><tr><th>Талант</th><th>Эффект</th><th>Кому полезен</th></tr></thead><tbody><tr><td><b>Omnissiah's Chosen</b></td><td>Удваивает эффект аугметики</td><td>Поздние сборки с несколькими имплантами</td></tr><tr><td><b>Devoted Practitioner</b></td><td>+1 дополнительное очко на рангах 3, 5 и 9; опыт набирается медленнее</td><td>Любому ключевому герою</td></tr><tr><td><b>Skull Keeper</b></td><td>+1 заряд каждому сервочерепу</td><td>Саппорт / сборщик семян</td></tr><tr><td><b>Quartermaster</b></td><td>+1 заряд гранат</td><td>Гренадер</td></tr><tr><td><b>Throwing Arm</b></td><td>+5 дальности броска гранат</td><td>Гренадер</td></tr><tr><td><b>Aegis Adept</b></td><td>+2 брони от Aegis Shield</td><td>Танк</td></tr><tr><td><b>Provident</b></td><td>+1 патрон в магазине</td><td>Пургатор</td></tr><tr><td><b>Duelist</b></td><td>+10% вероятности наложения эффектов ближним оружием</td><td>Эффектный melee-билд</td></tr><tr><td><b>Venerable Soul</b></td><td>+1 WP</td><td>Библиарий / Юстикар</td></tr></tbody></table></div><div class=\"note tip\"><b>Совет</b><div>Если нашёл Инцептора с Devoted Practitioner или хорошим критическим талантом, это весомая причина развивать его. Но гнаться за идеальными случайными характеристиками необязательно.</div></div>","refs":["traits"],"tags":["таланты","пассивки","traits","способности"]},{"id":"ship","title":"Корабль: порядок прокачки","group":"Кампания","summary":"Самая сильная экономика Baleful Edict","body":"<p><b>Servitors</b> — строительство; <b>Requisition</b> — награды за миссии; <b>Seeds</b> — исследования и улучшение вещей. Это три разных ресурса.</p><h3>Оптимальный порядок</h3><ol><li><b>Augmentation Chamber</b> — пассивно производит сервиторов, выгоднее всего построить пораньше.</li><li><b>Warp Drive I</b> — скорость перемещения и больше доступных миссий; при нехватке ресурсов можно переставить с первым пунктом.</li><li><b>Meditation Chamber</b> — ускоряет опыт рыцарей.</li><li><b>Reactor</b> — по необходимости, когда открывает путь к нужным модулям.</li><li><b>Warp Drive II–III + Enhanced Geller Field</b> — ускорение перелётов, игнорирование опасности варп-штормов.</li><li><b>Barracks</b> — расширение, когда не хватает мест. <b>Regeneration Unit</b> — когда ранения мешают миссиям.</li><li><b>Surgical Unit / Stasis Chamber</b> — для аугметики и Commune.</li><li><b>Augurium</b> — размещение Прогностикаров; прежде желательно понимать полную карту.</li><li><b>Void Shields / Gun Batteries</b> — при риске корабельных боёв, после экономических модулей.</li></ol><h3>Как выбирать миссии на карте</h3><ul><li>Сначала предотвращай угрозы <b>Morbus Gate</b>: пять неостановленных врат — поражение.</li><li>В начале особенно ценны награды <b>Servitors</b> и ресурсы для развития.</li><li>Не гоняйся за каждой вспышкой Bloom: приоритет — большая прибавка заражения, близость, нужный предмет/рыцарь.</li><li>Смотри на время полёта и срок жизни миссии до отправления.</li></ul><div class=\"note tip\"><b>Ремонт корпуса</b><div>Если планируешь улучшать Void Shields, сначала проверь сам апгрейд: бывает выгоднее, чем просто чинить ущерб.</div></div>","refs":["ship","pcg","classguide"],"tags":["корабль","servitors","двигатель","сервиторы","выживание"]},{"id":"prognosticars","title":"Прогностикары: где ставить","group":"Кампания","summary":"Шесть ключевых систем после расширения звёздной карты","body":"<p>Прогностикары устанавливаются через <b>Augurium</b> и усиливаются исследованиями в Libris Malleus. Они дают боевые бонусы в зоне действия, в том числе дополнительный слот стратагемы, а также помогают со стратегическим заражением.</p><div class=\"note warn\"><b>Не ставь их наугад</b><div>Карту расширят после сюжетного этапа. Позиции неудобно менять, поэтому в начале лучше держать запас.</div></div><h3>Подтверждённая сообществом схема покрытия 33 систем</h3><ul><li><b>Ur-Tet</b></li><li><b>Y'zheim</b></li><li><b>Caaleph</b></li><li><b>Amalrich</b></li><li><b>Fides</b></li><li><b>Pentragast</b></li></ul><p><a href=\"https://www.youtube.com/watch?v=d-yiPilsGgg\" target=\"_blank\" rel=\"noopener\">Видео с точным размещением на карте и объяснением покрытия</a>. Это куда точнее схемы по списку названий.</p><h3>Когда строить</h3><ul><li>Первые Прогностикары полезны, когда зона накрывает постоянные миссии.</li><li>Массовую расстановку лучше делать <b>после расширения карты</b>.</li><li>Исследования их бонусов работают только на покрытой территории.</li><li>Не забывай заполнять дополнительный слот стратагемы перед высадкой.</li></ul><p>Прогностикары не заменяют <a href=\"#research\">исследования</a> и <a href=\"#ship\">скорость двигателя</a>.</p>","refs":["prognost","classguide","pcg"],"tags":["прогностики","планеты","схема","поставить"]},{"id":"research","title":"Исследования и семена","group":"Кампания","summary":"Extractor Skull, Gate of Infinity и Purity Seals","body":"<h3>Что исследовать прежде всего</h3><ol><li><b>Advanced Seed Access</b> — открывает Extractor Servo-Skull и повышает получаемые семена.</li><li><b>Advanced Seed Extraction</b> — дополнительное семя при извлечении.</li><li><b>Gate of Infinity</b> — стратагема переноса всей четвёрки в видимую область.</li><li><b>Quicksilver</b> — выбранный боец получает +2 AP.</li><li><b>Enhanced Attunement</b> — дополнительный слот стратагемы.</li><li><b>Bloom Suppression</b> — медленнее заполняется Warp Surge.</li><li><b>Purity Seals</b> после The Nexus — позволяет улучшать вещи семенами.</li><li>Сюжетные исследования — по мере необходимости для продвижения кампании.</li></ol><h3>Как добывать семена</h3><ul><li><b>Extractor Servo-Skull</b> снимает семя с носителя на расстоянии без расхода AP.</li><li><b>Hammerhand</b> даёт гарантированный критический melee-удар, который можно направить в семя.</li><li><b>Extract Seed</b> у Apothecary — извлечение семян с обычных ударов в ближнем бою.</li><li>Ищи заражённые объекты на карте и проверяй носителей до финального убийства.</li></ul><h3>Улучшение оружия — пошагово</h3><ol><li>Пройди <b>The Nexus</b>.</li><li>Изучи <b>Purity Seals</b> в Libris Malleus.</li><li>Зайди в <b>Barracks → Knight → Loadout</b>.</li><li>Выбери конкретное оружие или броню и открой панель улучшений.</li><li>Потрать нужные <b>цвета семян</b> на выбранные свойства.</li></ol><div class=\"note tip\"><b>Лучшие вложения</b><div>Дополнительные AP, шанс критического удара, Focus, WP, дальность и магазин обычно полезнее случайной прибавки HP. Береги семена для сюжетных исследований.</div></div><p>См. также <a href=\"#gear\">приоритеты экипировки</a>.</p>","refs":["research","gear","pcg"],"tags":["семена","апгрейд","purity seals","улучшать","стратагемы"]},{"id":"gear","title":"Оружие, броня, варгир","group":"Арсенал","summary":"Что выдавать героям и что улучшать семенами","body":"<p>Смотри на <b>синергию предмета с навыками</b>. Удачный Tier II иногда лучше неподходящего Tier III. Дополнительное AP практически всегда чрезвычайно ценно.</p><h3>Кому что выдавать</h3><div class=\"table-wrap\"><table><thead><tr><th>Класс</th><th>Ближнее/дальнее оружие</th><th>Броня и предметы</th></tr></thead><tbody><tr><td>Interceptor</td><td>Меч или фальшионы с критическим шансом; Storm Bolter — вторичен</td><td>Power Armour с AP / Move / Focus; Augurium Scrolls, Sanctic Shard</td></tr><tr><td>Justicar</td><td>Молот/меч; Storm Bolter или Psycannon при открытии ветки</td><td>Terminator Armour с WP; Sacred Incense</td></tr><tr><td>Librarian</td><td>Оружие со свойствами WP/защиты</td><td>Terminator Armour с WP; Sacred Incense</td></tr><tr><td>Purgator</td><td>Psilencer с дальностью, критом; или Psycannon для AoE</td><td>Power Armour с AP; Extended Magazine, Blessed Greaves</td></tr><tr><td>Apothecary</td><td>Narthecium/оружие ближнего боя по роли</td><td>Броня с WP, сервочерепа для удалённой помощи</td></tr><tr><td>Chaplain</td><td>Crozius с полезными дебаффами</td><td>Terminator Armour с WP и защитой</td></tr><tr><td>Paladin</td><td>Молот/алебарда; Storm Shield для обороны</td><td>Terminator Armour с бронёй/WP</td></tr><tr><td>Purifier</td><td>Incinerator; гранаты как специализация</td><td>Броня с бонусами гранат и дополнительных зарядов</td></tr></tbody></table></div><h3>Главные категории аксессуаров</h3><ul><li><b>Augurium Scrolls</b> — шанс крита ближнего боя.</li><li><b>Sanctic Shard</b> — Focus: повышает вероятность автоматических умений.</li><li><b>Sacred Incense</b> — максимальный WP.</li><li><b>Blessed Greaves</b> — шанс крита в дальнем бою.</li><li><b>Extended Magazine</b> — размер магазина.</li><li><b>Extractor Servo-Skull</b> — семена без AP.</li><li><b>Autoloader Skull</b> — бесплатная перезарядка.</li><li><b>Seeker Skull</b> — помечает врагов без активации патруля и даёт Vulnerable (Update XIII).</li></ul><h3>Какие гранаты брать</h3><div class=\"table-wrap\"><table><thead><tr><th>Тип</th><th>Эффект</th></tr></thead><tbody><tr><td>Frag</td><td>Урон и Knockback — сбросить с обрыва.</td></tr><tr><td>Krak</td><td>Разрушение брони тяжёлого противника.</td></tr><tr><td>Psychotroke</td><td>Crazed — часть ходов враг может действовать против союзников (не гарантировано).</td></tr><tr><td>Psyk-Out</td><td>Silenced — запрет психических способностей.</td></tr><tr><td>Empyrean Brain Mine</td><td>Много Stun для подготовки Execute.</td></tr></tbody></table></div><div class=\"note tip\"><b>Важная поправка</b><div>Некоторые специальные предметы из предзаказов и других DLC не входят в твой набор контента. Вики не опирается на них как на обязательную экипировку.</div></div>","refs":["pcg","classguide","patch13"],"tags":["оружие","броня","лут","аксессуары","гранаты","сервочереп"]},{"id":"ap","title":"AP, Stun и Execute","group":"Тактика","summary":"Три самые важные боевые экономики","body":"<h3>AP — очки действий</h3><p>У бойца обычно 3 AP в начале хода. Ближняя атака, стрельба, перемещение и большинство умений тратят AP. Дополнительные действия могут дать <b>Honour the Chapter, Quicksilver, Ruthless Precision</b>.</p><div class=\"note tip\"><b>Трюк с первым контактом</b><div>Когда новая группа противников обнаружена вне боя, AP всей команды <b>обновляются до 3</b>. Значит, до контакта выгодно подвести бойцов ближе и использовать разумные подготовительные действия. Но лимиты автоматических способностей могут вести себя отдельно.</div></div><h3>Execute — источник новых AP</h3><ol><li>Накопи Stun врагу атаками, эффектами Iron Arm, Brain Mine, Psychic Shriek и др.</li><li>После полного оглушения нанеси подходящий удар ближнего боя и выбери <b>Execute</b>.</li><li>Команда получит дополнительные AP. <b>Litany of Hate</b> Chaplain усиливает эту связку.</li></ol><p>На Legendary пороги Stun выше, поэтому пытаться доводить до Execute каждого противника — ошибка. Делай это только в сборке, рассчитанной на оглушение.</p><h3>Focus — что это на самом деле</h3><p>Focus влияет на шанс срабатывания <b>автоматических способностей</b> вроде Ruthless Precision; Focus не тождественен шансу критического удара. Нужны и Crit Chance, и Focus.</p><h3>WP — психическая энергия</h3><p>Она расходуется на заклинания и усиленные атаки. Убийства помогают её восстанавливать, но массовая атака не гарантирует WP за каждого поражённого врага. Не опустошай Библиария перед важным столкновением.</p>","refs":["pcg","classguide","patch"],"tags":["ap","очки действий","вп","stun","execute","крит","focus"]},{"id":"combat","title":"Как двигаться и побеждать","group":"Тактика","summary":"Патрули, разведка, окружение и контроль","body":"<h3>Пошаговое открытие группы</h3><ol><li>На карте найди зелёный маркер патруля и направление его движения.</li><li>Подведи <b>отставших</b> рыцарей. Оставь мобильного разведчика последним.</li><li>Прежде чем открывать врагов, проверь AP, WP и перезарядку.</li><li>Если есть Seeker Skull, сначала пометь противников без активации группы.</li><li>Раскрой группу одним рыцарем и обнови AP команды.</li><li>Уничтожь <b>бафферов и угрозы немедленного убийства</b>, затем опасных стрелков; мелочь — в последнюю очередь.</li></ol><h3>Три варианта первого хода</h3><ul><li><b>Контроль:</b> Astral Aim или Hammerhand отключает основной ствол/способность. Это лучше слабого урона.</li><li><b>Атака:</b> Юстикар выдаёт AP Инцептору, тот уничтожает ключевые цели с критами.</li><li><b>Массовое поражение:</b> взорви контейнер, опрокинь колонну или сбрось группу с края гранатой.</li></ul><h3>Правильное позиционирование</h3><ul><li>Не открывай две группы за раз.</li><li>Не ставь всю команду рядом с огнемётчиком или гранатомётчиком.</li><li>Укрываться важнее, когда опасные враги переживут твой ход.</li><li>Помни про высоту, полное укрытие и простреливаемые линии.</li><li>Проверяй красные предупреждающие зоны и смертельные механики захвата.</li><li>На миссиях защиты Overwatch полезнее, чем на миссиях зачистки.</li></ul><h3>Микротрюки</h3><ul><li>Значительную часть сближения для melee-ударов можно включить в саму атаку, сэкономив AP.</li><li>Knockback возле пропасти способен убить даже толстого врага.</li><li>Не расходуй дорогие психические заклинания на простых Poxwalkers, если их можно убрать взрывом.</li><li>Сначала убей Nurgling Swarm / Preacher / Plague Surgeon — их поддержка удлиняет бой.</li><li>Перед Warp Surge старайся закончить контакт или сохранить достаточно AP для реакции.</li></ul>","refs":["pcg","patch","patch13"],"tags":["разведка","движение","патрули","побеждать","легендарная"]},{"id":"formations","title":"Лучшие отряды","group":"Тактика","summary":"Четвёрки под Legendary и первые миссии","body":"<div class=\"table-wrap\"><table><thead><tr><th>Название</th><th>Четвёрка</th><th>Как работает</th></tr></thead><tbody><tr><td><b>Универсальная S</b></td><td>Interceptor + Justicar + Librarian + Purgator</td><td>Телепорт, AP, дальний контроль, убийца.</td></tr><tr><td><b>Ранняя игра</b></td><td>Interceptor + Justicar + Purgator + Apothecary</td><td>Warp Speed на Инцептора; Honour the Chapter и дальний огонь.</td></tr><tr><td><b>Агрессивная</b></td><td>Interceptor + Interceptor + Justicar + Librarian</td><td>Два убийцы, групповая телепортация и AP-батарейка.</td></tr><tr><td><b>Стрельба</b></td><td>Purgator + Purgator + Chaplain + Justicar</td><td>Критический урон и Support Fire из безопасных позиций.</td></tr><tr><td><b>Оборона</b></td><td>Purgator + Paladin + Chaplain + Justicar</td><td>Удержание узких проходов, AoE и защита.</td></tr></tbody></table></div><h3>Два важнейших взаимодействия</h3><ul><li><b>Justicar → Interceptor:</b> Honour the Chapter превращает WP Юстикара в дополнительные атаки самого сильного бойца. Смотри <a href=\"#interceptor\">билд Инцептора</a>.</li><li><b>Librarian → все:</b> усиленная Gate of Infinity переносит всю команду рядом с приоритетной целью. Смотри <a href=\"#librarian\">билд Библиария</a>.</li></ul><p>Не делай весь резерв из одного класса. Финальная битва требует восьмерых рыцарей; вторая команда должна самостоятельно уничтожать подкрепления.</p>","refs":["classguide","forum"],"tags":["отряд","команда","состав","синергия"]},{"id":"classes","title":"Тирлист и классы","group":"Классы","summary":"Кого качать в первую очередь и почему","body":"<div class=\"table-wrap\"><table><thead><tr><th>Место</th><th>Класс</th><th>Роль / оценка</th></tr></thead><tbody><tr><td>S+</td><td><b><a href=\"#interceptor\">Interceptor</a></b></td><td>Лучший убийца; телепорт, криты, AP.</td></tr><tr><td>S</td><td><b><a href=\"#justicar\">Justicar</a></b></td><td>Передача AP и броня.</td></tr><tr><td>S</td><td><b><a href=\"#librarian\">Librarian</a></b></td><td>Групповой телепорт, контроль.</td></tr><tr><td>A+</td><td><b><a href=\"#purgator\">Purgator</a></b></td><td>Дальний огонь, Astral Aim, гранаты.</td></tr><tr><td>A</td><td><b><a href=\"#chaplain\">Chaplain</a></b></td><td>Литании критов и Execute.</td></tr><tr><td>B+</td><td><b><a href=\"#apothecary\">Apothecary</a></b></td><td>Warp Speed, лечение, семена.</td></tr><tr><td>B</td><td><b><a href=\"#paladin\">Paladin</a></b></td><td>Танк и конусный AoE.</td></tr><tr><td>B</td><td><b><a href=\"#purifier\">Purifier</a></b></td><td>Огнемёт и гранаты.</td></tr><tr><td>A*</td><td><b><a href=\"#crowe\">Garran Crowe</a></b></td><td>Готовый уникальный герой; фиксированный билд.</td></tr></tbody></table></div><p>Это субъективный рейтинг силы в составе, заточенном под Legendary, а не официальные характеристики. Из-за экипировки и сценария отдельный класс может подняться существенно выше.</p><div class=\"note tip\"><b>Кого качать первым</b><div>Interceptor → Justicar → Purgator; Apothecary помогает до появления Librarian. Дальше — ещё один Interceptor или Chaplain по любимому стилю.</div></div>","refs":["classguide","classes","forum"],"tags":["тирлист","персонажи","герои"]},{"id":"interceptor","title":"Interceptor — билд S+","group":"Классы","summary":"Телепортирующийся убийца с возвратом AP","body":"<h3>Качать в первую очередь</h3><ol><li><b>Teleport</b> — перемещение на расстояние.</li><li><b>Teleport Range</b> — дальше телепорт.</li><li><b>Teleport Strike</b> — атака с телепортацией против нескольких врагов.</li><li><b>Teleport Boost</b> — шанс получить AP после телепорта.</li><li><b>Hammerhand</b> — гарантированный крит и выбор точки поражения.</li><li><b>Ruthless Precision</b> — шанс вернуть AP при критическом ударе.</li><li><b>Melee Critical Chance</b> и <b>Enduring Reflexes</b> — частые и многократные автоэффекты.</li></ol><h3>Снаряжение</h3><ul><li>Силовой меч или фальшионы с <b>критическим шансом</b>.</li><li>Power Armour с <b>+AP, Move, Focus</b>.</li><li>Augurium Scrolls (крит), Sanctic Shard (автоэффекты), Liber Daemonicum (критический урон).</li></ul><h3>Как играть</h3><p>Юстикар передаёт AP → Инцептор телепортируется к опасной цели → Hammerhand отключает её пушку или извлекает семя → критами и добиваниями возвращает действия. Не начинай в одиночку посреди вражеской армии.</p><div class=\"note tip\"><b>Проверка билда</b><div>Если у Инцептора нет Teleport, он теряет главное преимущество. В этом случае разумно рассмотреть Retrain.</div></div>","refs":["classguide","forum"],"tags":["инцептор","билд","crit","teleport"]},{"id":"justicar","title":"Justicar — билд S","group":"Классы","summary":"Батарейка AP и защитный саппорт","body":"<h3>Ключевые навыки</h3><ol><li><b>Honour the Chapter</b> — передаёт AP союзнику; усиление добавляет ещё действия за WP.</li><li><b>Максимальный WP</b> — больше применений способности.</li><li><b>Hammerhand</b> — гарантированный крит для семени/отключения пушки.</li><li><b>Fortress</b> — отдаёт броню выбранному союзнику.</li><li><b>Aegis Shield</b> и броня — безопасность переднего края.</li></ol><h3>Снаряжение</h3><p>Terminator Armour с бонусом WP, Sacred Incense (+WP), тяжёлое melee-оружие. Psycannon — лишь если сознательно открываешь ветку.</p><h3>Главная синергия</h3><p>Не обязательно делать Юстикара главным танком. Его лучшие ходы часто состоят из передачи AP Инцептору, а не собственной атаки.</p>","refs":["classguide"],"tags":["юстикар","honour","поддержка"]},{"id":"purgator","title":"Purgator — билд A+","group":"Классы","summary":"Psilencer, Astral Aim или гранаты","body":"<h3>Вариант 1: точный стрелок</h3><ol><li><b>Psilencer Discipline</b> — дальность и критический урон.</li><li><b>Astral Aim</b> — гарантированная дальняя критическая атака с выбором части тела.</li><li><b>Ranged Ammo</b> — больше патронов.</li><li><b>Mental Focus</b> — шанс вернуть AP после дальнего крита.</li><li><b>Support Fire</b> — автоматический дополнительный выстрел при атаке союзника.</li></ol><h3>Вариант 2: гранатомётчик</h3><ul><li><b>Grenade Slot / Ammo / Area</b> — больше гранат и радиус.</li><li><b>Sanctified Kill Zone</b> — накладывает Vulnerable: цели получают больше урона от следующих атак.</li><li>Frag у пропастей; Krak по броне; Psychotroke для контроля.</li></ul><h3>Снаряжение</h3><p>Psilencer с дальностью, критом и магазином; Power Armour с AP; Blessed Greaves для шанса дальнего крита, Extended Magazine для боезапаса.</p><div class=\"note tip\"><b>Не распыляй очки</b><div>Не нужно развивать все ветки тяжёлого оружия: выбери одну главную роль и добирай полезные общие навыки.</div></div>","refs":["classguide","classes"],"tags":["пургатор","псиленсер","гранатомёт"]},{"id":"apothecary","title":"Apothecary — билд B+","group":"Классы","summary":"Биомантия полезнее, чем бесконечное лечение","body":"<h3>Сильные навыки</h3><ol><li><b>Warp Speed Biomancy</b> — усиливает скорость и урон критов ближнего боя союзника.</li><li><b>Iron Arm Biomancy</b> — удары союзника сильнее оглушают.</li><li><b>Endurance Biomancy</b> — сопротивление и очистка негативных статусов.</li><li><b>Apothecarion Servo-Skull</b> — применять биомантию на расстоянии.</li><li><b>Surgical Adept</b> — шанс вернуть AP за биомантию.</li><li><b>Extract Seed</b> — получать семена при melee-ударе.</li></ol><p>Warp Speed особенно силён на Инцепторе с гарантированными и частыми критами.</p><h3>Снаряжение</h3><p>Narthecium для лечебного билда; медикаменты и сервочерепа, броня с WP. Это отличный ранний четвёртый боец, позднее его можно сменить на Librarian.</p>","refs":["classes","pcg"],"tags":["апотекарий","доктор","лекарь","биомантия"]},{"id":"librarian","title":"Librarian — билд S","group":"Классы","summary":"Контроль поля и телепорт всей команды","body":"<h3>Прокачка</h3><ol><li><b>Gate of Infinity + Warp Charge</b> — возможность перенести всю четвёрку, а не только себя.</li><li><b>Gate Range</b> — дальность переноса.</li><li><b>Psychic Shriek</b> — массовое оглушение и Disrupted (блок автоумений).</li><li><b>Vortex of Doom</b> — мощный психический урон по площади.</li><li><b>Empyrean Domination</b> — снижение Warp Surge.</li><li><b>Sanctuary</b> — броня группе.</li></ol><p>На Legendary главное — перенос всей команды и безопасное отключение реакций. Не расходуй весь WP на обычную мелочь.</p><h3>Экипировка</h3><p>Terminator Armour с WP; Sacred Incense. Броня и оружие, повышающие запас WP, приоритетнее обычного шанса критов.</p>","refs":["classes","classguide"],"tags":["библиарий","маг","gate"]},{"id":"chaplain","title":"Chaplain — билд A","group":"Классы","summary":"Литании на критические атаки и Execute","body":"<h3>Главные литании</h3><ul><li><b>Litany of Hate</b> — дополнительное AP исполнителю Execute.</li><li><b>Intonement for Guidance</b> — бонус шанса критического выстрела.</li><li><b>Words of Power</b> — повышенный критический урон.</li><li><b>Invocation of Focus</b> — шанс восстановить WP при усиленных психических способностях.</li><li><b>Refrain of Convergence</b> — сопротивление статусам.</li><li><b>Litany of Faith</b> — сильнее броня от Aegis Shield.</li></ul><p>Качай Litany of Hate для Stun-команды, а Intonement for Guidance — для команды с двумя Пургаторами. Одновременно активна одна литания одного Капеллана.</p><h3>Экипировка</h3><p>Crozius с полезным дебаффом (например Vulnerable), Terminator Armour с WP, Sacred Incense.</p>","refs":["classes"],"tags":["капеллан","литании"]},{"id":"paladin","title":"Paladin — билд B","group":"Классы","summary":"Защитник и психический конусный урон","body":"<h3>Два варианта</h3><ul><li><b>Fury of the Ancients</b> — конусная психическая атака с отбрасыванием; сильна после усилений.</li><li><b>Storm Shield / Defend Position</b> — защитная зона и броня для удержания точки.</li><li><b>Smite</b> — психический точечный урон.</li><li><b>The Emperor's Will</b> — передача WP союзнику.</li></ul><h3>Снаряжение</h3><p>Terminator Armour с бронёй или WP; Storm Shield вместо дальнего оружия в оборонительном билде, молот/алебарда с Stun.</p><div class=\"note tip\"><b>Когда брать</b><div>Для оборонительных миссий и узких проходов полезнее, чем для быстрых наступательных зачисток. Не пытайся играть им как мобильным Инцептором.</div></div>","refs":["paladin","classes"],"tags":["паладин","щит"]},{"id":"purifier","title":"Purifier — билд B","group":"Классы","summary":"Огнемёт, Burning и гранаты","body":"<h3>Направления прокачки</h3><ul><li><b>Incinerator Discipline</b> — больше урон, сектор и дальность огнемёта.</li><li><b>Flames of Purity</b> — усиленная огненная атака.</li><li><b>Wargear Discipline</b> — усиленные гранаты и заряды.</li><li><b>Cleansing Flame</b> — огонь с Purge: удаляет мутации врагов.</li><li><b>Vengeance</b> — возврат AP при нескольких убийствах одной атакой.</li></ul><p>Лучше всего работает против групп слабой и средней пехоты. Для точечного отключения элитных врагов обычно удобнее Пургатор с Astral Aim.</p><h3>Снаряжение</h3><p>Incinerator с дальностью и уроном; Frag/Krak гранаты, броня с улучшением гранат.</p>","refs":["classes"],"tags":["пурифаер","очиститель","огонь"]},{"id":"crowe","title":"Castellan Garran Crowe","group":"Классы","summary":"Единственный разрешённый DLC-герой в этом гайде","body":"<p>Гарран Кроу — уникальный персонаж с фиксированным развитием и экипировкой. Появляется после сюжетного продвижения; патч уточнял его прибытие <b>через 15 дней после первого отчёта Великому магистру после The Nexus</b>.</p><h3>Что умеет</h3><ul><li><b>Black Blade of Antwyr</b> — его уникальный меч.</li><li><b>Rend the Unclean</b> — удар по области вокруг Кроу.</li><li><b>Crushing Charge</b> — рывок через противников.</li><li><b>Empyrean Domination</b> — уменьшение Warp Surge.</li><li><b>First Strike</b> — автоатака по сблизившемуся врагу.</li></ul><p>Не распределяешь ему обычные очки навыков и не меняешь стандартную экипировку; аугметику он не получает. Хорош, когда нужен готовый сильный рыцарь вместо раненых специалистов.</p><div class=\"note tip\"><b>Место в рейтинге</b><div>Примерно A: отличный готовый герой, но идеально собранный Инцептор с редкой экипировкой обычно эффективнее.</div></div>","refs":["patch","patch13"],"tags":["кроу","кастелян","crowe"]},{"id":"enemies","title":"Мобы: опасности и контры","group":"Враги","summary":"Кого убивать первым, кого выключать критом","body":"<div class=\"note tip\"><b>Приоритет на Legendary</b><div><b>Ритуал/мгновенное убийство → лекари и призыватели → опасное оружие и автоатаки → остальная пехота</b>. Это не строгий порядок: смотрите на конкретную позицию и AP.</div></div><h3>Культисты, ходячие мертвецы</h3><div class=\"table-wrap\"><table><thead><tr><th>Кто</th><th>Опасность</th><th>Контра</th></tr></thead><tbody><tr><td>Apostate / Bloomspawn Preacher</td><td>Проводит ритуал, усиливает/мутирует других</td><td><b>Критично:</b> убрать первым или наложить Silenced</td></tr><tr><td>Heavy Stubber Cultist</td><td>Suppressive Fire наказывает за действия и движение</td><td>Astral Aim/Hammerhand по оружию; быстрое убийство</td></tr><tr><td>Grenadier Cultist</td><td>Гранаты и Pinned могут лишить AP</td><td>Убить до его первого хода</td></tr><tr><td>Bloated Poxwalker</td><td>Опасный взрыв при смерти; Plagued</td><td>Убить издали, не стоять рядом</td></tr><tr><td>Poxwalkers</td><td>Опасны группой и окружением</td><td>AoE, гранаты, взрывы окружения</td></tr></tbody></table></div><h3>Death Guard</h3><div class=\"table-wrap\"><table><thead><tr><th>Кто</th><th>Опасность</th><th>Контра</th></tr></thead><tbody><tr><td>Plague Surgeon</td><td>Лечит, усиливает мутации, восстанавливает части тела</td><td><b>Приоритет №1</b> в группе</td></tr><tr><td>Noxious Blightbringer</td><td>Обнуляет броню от Aegis и Fortress</td><td>Быстро уничтожить; не играть от защитных баффов</td></tr><tr><td>Lord of Virulence</td><td>Тяжёлый AoE и поддержка</td><td>Disrupted и фокус</td></tr><tr><td>Plague Marine — Meltagun</td><td>Разрушает броню</td><td>Отключить оружие критом</td></tr><tr><td>Plague Marine — Belcher</td><td>Огнемётный конус</td><td>Развести рыцарей, дистанционный урон</td></tr><tr><td>Blightlord Terminator</td><td>Толстая броня, тяжёлый огонь</td><td>Krak / Armour Break, отключить орудие</td></tr></tbody></table></div><h3>Демоны и крупные мутанты</h3><div class=\"table-wrap\"><table><thead><tr><th>Кто</th><th>Опасность</th><th>Контра</th></tr></thead><tbody><tr><td>Nurgling Swarm</td><td>Поднимает и мутирует Poxwalkers, усиливает демонов</td><td><b>Сразу уничтожить</b></td></tr><tr><td>Chaos Spawn</td><td>Death Grip — способен убить захваченного рыцаря</td><td>Спасти жертву в первую очередь; Disrupted прерывает опасную автоатаку</td></tr><tr><td>Beast of Nurgle</td><td>Метка смертельной атаки, обездвиживание</td><td>Не игнорировать помеченного, быстро ликвидировать зверя</td></tr><tr><td>Plaguebearer / Plagueridden</td><td>Мутации и живучесть</td><td>Purge, дистанционный урон; не давать окружить</td></tr></tbody></table></div><h3>Машины и тяжёлая техника</h3><div class=\"table-wrap\"><table><thead><tr><th>Кто</th><th>Опасность</th><th>Контра</th></tr></thead><tbody><tr><td>Helbrute</td><td>Плазменное оружие, рывок, захват</td><td>Disrupted, дистанция, точечные повреждения</td></tr><tr><td>Myphitic Blight-Hauler</td><td>Броня и ракетный AoE</td><td>Krak / Armour Break, затем концентрированный урон</td></tr><tr><td>Foetid Bloat-Drone</td><td>Реакционная стрельба и AoE</td><td>Disrupted перед стрельбой; психический или melee-урон</td></tr><tr><td>Fleshmower Drone</td><td>Опасный рывок ближнего боя</td><td>Уничтожать до сближения; не стоять на линии</td></tr><tr><td>Nurgle War Dog Stalker</td><td>Много брони, ракеты; иммунитет к Armour Pierce</td><td><b>Ломай броню</b>, не пытайся пробить её насквозь</td></tr></tbody></table></div><h3>Неподвижные объекты</h3><ul><li><b>Bloomspawn Spreader</b> — главная цель заражения; заранее готовь burst-урон, иначе подкрепления затянут бой.</li><li><b>Bloom Sprouts/Stems</b> — дальние атаки, Pinned и опасные зоны; уничтожай, если блокируют подход.</li><li><b>Gnarlmaw и прочие гнёзда</b> — источники постоянных дополнительных угроз.</li></ul><div class=\"note warn\"><b>Смертельные значки</b><div>После Update XIII красный символ уничтожения явно предупреждает об атаках типа Death Grip / Attention Seeker. Если появился — немедленно спасай рыцаря.</div></div>","refs":["patch","patch13","pcg"],"tags":["монстры","враги","мобы","контры","death guard"]},{"id":"bosses","title":"Боссы: как побеждать","group":"Враги","summary":"Reapers, Kadex и Mortarion — сюжетные спойлеры","body":"<div class=\"spoiler-head\"><span>⚠️ В этом разделе раскрываются имена сюжетных боссов и их механики.</span></div><h3>Рейтинг сложности (практический, не официальный)</h3><div class=\"table-wrap\"><table><thead><tr><th>Босс</th><th>Условная сложность</th><th>Главная идея</th></tr></thead><tbody><tr><td>Aeger the Benevolent</td><td>★★★☆☆</td><td>Уничтожать гнёзда Nurglings и быстро фокусить</td></tr><tr><td>Cruciatus the Generous</td><td>★★★☆☆</td><td>Снимать броню; использовать окружение</td></tr><tr><td>Morgellus</td><td>★★★★☆</td><td>Следить за разрушением пола; ломать защиту</td></tr><tr><td>Malathian the Harvester</td><td>★★★★★</td><td>Сносить Effigies и заканчивать бой быстро</td></tr><tr><td>Munificus the Undying</td><td>★★★★★ без критов</td><td>Гарантированные криты по частям тела</td></tr><tr><td>Kadex</td><td>★★★☆☆</td><td>Отключать реакции и контролировать копии</td></tr><tr><td>Mortarion</td><td>★★★★★</td><td>Две полноценные команды</td></tr></tbody></table></div><details class=\"boss\"><summary>Aeger — Nurglings и гнёзда</summary><p>Гнёзда постоянно производят мелких демонов, которых босс использует для защиты и восстановления. Сноси ближайшие гнёзда AoE, не позволяй стае блокировать линии стрельбы и быстро добивай основную цель. Psilencer и гранаты хороши.</p></details><details class=\"boss\"><summary>Cruciatus — гигант с бронёй</summary><p>Нужны Krak и Armour Break. Выстрелы позволяют выманивать босса к взрывным объектам или обрушениям. Не пытайся полностью решить его пушечную механику стандартным удалением оружия критами. Разведи рыцарей по разным сторонам.</p></details><details class=\"boss\"><summary>Morgellus — разрушающаяся арена</summary><p>Сначала отключи защитные механизмы, мешающие критам и дальнему урону. Обязательно сильный melee. Следи, какие платформы могут разрушиться: падение рыцаря — гораздо хуже обычного урона. Библиарий с групповым переносом полезен.</p></details><details class=\"boss\"><summary>Malathian — четыре Effigy</summary><p>Идолы создают опасные эффекты: <b>Death</b> угрожает убийством; <b>Infirmity</b> блокирует лечение; <b>Despair</b> наказывает использование WP; <b>Suffering</b> наносит периодический урон. Уничтожай актуальную опасную Effigy, разруши броню и не затягивай бой.</p></details><details class=\"boss\"><summary>Munificus — проверка гарантированных критов</summary><p>Босс регенерирует. Уменьшать его максимальную живучесть нужно через Precision Targeting по частям тела. Приводи <b>Hammerhand и Astral Aim</b>. Меняй направление подхода и не трать ход на бессмысленный обычный урон.</p></details><details class=\"boss\"><summary>Kadex — телепортация и копии</summary><p>Проверяй конкретную сюжетную цель: иногда нужно не убить его, а защитить объект/дождаться исхода. Disrupted помогает лишить реакций, а концентрированный урон — не тратить AP на отвлечение.</p></details><details class=\"boss\"><summary>Mortarion — финальное сражение</summary><p>Нужны <b>две четвёрки</b>: одна с Кальдором Драйго сражается с боссом, вторая удерживает врагов у портала. Корни Мора уничтожает Драйго после фаз повреждения. Стратагемы недоступны; нужно копить WP и беречь оба отряда. Атака: Interceptor, Justicar, Librarian, Purgator. Оборона: Purgator, Chaplain, Justicar, ещё один стрелок/Interceptor.</p></details><div class=\"note warn\"><b>Важно для кампании</b><div>В нормальной истории за одну кампанию сражаются не со всеми пятью Reaper; порядок зависит от выборов и сюжета. Не подбирай состав слепо — читай механику каждого перед вылетом.</div></div>","refs":["bosses","patch"],"tags":["боссы","жнецы","мортарион","кадекс"]},{"id":"glossary","title":"Баффы, дебаффы и термины","group":"Справочник","summary":"Что именно делает каждый статус — простым языком","body":"<div class=\"table-wrap\"><table><thead><tr><th>Термин</th><th>Что делает</th></tr></thead><tbody><tr><td><b>AP</b></td><td>Очки действий: движение, атака, применение навыков.</td></tr><tr><td><b>WP</b></td><td>Психическая энергия для усилений, телепорта и заклинаний.</td></tr><tr><td><b>Armour</b></td><td>Поглощает урон до здоровья.</td></tr><tr><td><b>Focus</b></td><td>Повышает шанс автоматических эффектов; не то же самое, что Crit Chance.</td></tr><tr><td><b>Crit Chance</b></td><td>Вероятность критической атаки.</td></tr><tr><td><b>Crit Damage</b></td><td>Дополнительный урон критической атаки.</td></tr><tr><td><b>Stun</b></td><td>Заполняемая шкала оглушения; даёт гарантированный крит / Execute.</td></tr><tr><td><b>Disrupted</b></td><td>Блокирует автоматические реакции/способности.</td></tr><tr><td><b>Silenced</b></td><td>Запрещает психические способности.</td></tr><tr><td><b>Vulnerable</b></td><td>Следующие атаки наносят цели больше урона (обычно +2).</td></tr><tr><td><b>Pinned</b></td><td>На следующем ходу меньше AP; боссы иммунны.</td></tr><tr><td><b>Immobilized</b></td><td>Нельзя перемещаться.</td></tr><tr><td><b>Hobbled</b></td><td>Снижена дальность передвижения.</td></tr><tr><td><b>Blinded</b></td><td>Дальнобойные атаки слабее.</td></tr><tr><td><b>Weakened</b></td><td>Ближние атаки слабее.</td></tr><tr><td><b>Burning</b></td><td>Периодический огненный урон.</td></tr><tr><td><b>Plagued</b></td><td>Периодический чумной урон.</td></tr><tr><td><b>Bleed</b></td><td>В Update XIII урон равен накопленным зарядам, которые постепенно спадают.</td></tr><tr><td><b>Crazed</b></td><td>В Update VIII действует вероятностно: враг может действовать нормально либо как Dominated — не гарантированный контроль.</td></tr><tr><td><b>Dominated</b></td><td>Враг временно действует на стороне игрока и считается Disrupted.</td></tr><tr><td><b>Panicked</b></td><td>Враг пытается убежать.</td></tr><tr><td><b>Enraged</b></td><td>Враг стремится атаковать источник эффекта вблизи.</td></tr><tr><td><b>Drained</b></td><td>Утрата WP.</td></tr><tr><td><b>Punish the Witch</b></td><td>Урон при использовании WP.</td></tr><tr><td><b>Purify</b></td><td>Снимает негативные статусы с союзника.</td></tr><tr><td><b>Purge</b></td><td>Удаляет мутации с врага.</td></tr><tr><td><b>Armour Break</b></td><td>Уничтожает броню цели.</td></tr><tr><td><b>Armour Pierce</b></td><td>Проводит урон сквозь броню, если нет иммунитета.</td></tr><tr><td><b>Parry</b></td><td>Шанс заблокировать melee-атаку.</td></tr><tr><td><b>Support Fire</b></td><td>Автоматический выстрел при атаке союзника.</td></tr><tr><td><b>Warp Surge</b></td><td>Всплеск эффектов и подкреплений при заполнении шкалы варпа.</td></tr></tbody></table></div><div class=\"note tip\"><b>Особенно частые ошибки</b><div>Focus ≠ Crit Chance. Purge ≠ Purify. Armour Break ≠ Armour Pierce. Crazed ≠ гарантированная смена стороны.</div></div>","refs":["patch","patch13"],"tags":["бафф","дебафф","affliction","статусы","термины"]},{"id":"faq","title":"Частые вопросы","group":"Справочник","summary":"Короткие ответы на самые частые игровые непонятки","body":"<div class=\"faq\"><b>Как переобучить героя?</b><p><a href=\"#respec\">Retrain</a> через Barracks → Abilities за 2 Requisition; боец временно уйдёт на обучение.</p></div><div class=\"faq\"><b>Можно ли получить 10-й уровень?</b><p>Нет: максимум 9, но дополнительные навыки даёт <a href=\"#overcap\">Commune with the Fallen</a>.</p></div><div class=\"faq\"><b>Как получить импланты?</b><p>Построй Surgical Unit, затем рыцарь должен пережить Critical Wound и восстановиться. См. <a href=\"#augmetics\">аугметика</a>.</p></div><div class=\"faq\"><b>Где улучшать меч семенами?</b><p>После The Nexus и исследования Purity Seals: Barracks → Knight → Loadout. См. <a href=\"#research\">семена</a>.</p></div><div class=\"faq\"><b>Почему не появляются Библиарии?</b><p>Они доступны после сюжетного прогресса и наград миссий. См. <a href=\"#advanced\">продвинутые классы</a>.</p></div><div class=\"faq\"><b>Куда ставить Прогностикаров?</b><p>Есть схема из шести систем; см. <a href=\"#prognosticars\">точные названия и видео</a>.</p></div><div class=\"faq\"><b>Нужно ли спасать каждый заражённый мир?</b><p>Нет, ранняя игра предполагает распространение Bloom. Важнее сдерживать Morbus и выбирать миссии с максимальной отдачей. См. <a href=\"#ship\">стратегическая карта</a>.</p></div><div class=\"faq\"><b>Какие DLC входят в эту вики?</b><p>Только Castellan Garran Crowe. Другие DLC-классы и механики исключены.</p></div>","refs":["pcg","patch"],"tags":["вопросы","как","помощь"]}];
